<?php
require __DIR__.'/_admin.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$q=db()->prepare('SELECT attachment_name,attachment_original FROM quotations WHERE id=?');$q->execute([$id]);$row=$q->fetch();if(!$row||!preg_match('/^[a-f0-9]{36}\.(jpg|png|webp|pdf)$/',$row['attachment_name']??'')){http_response_code(404);exit('File not found');}
$file=realpath(__DIR__.'/../storage/private/'.$row['attachment_name']);$dir=realpath(__DIR__.'/../storage/private');if(!$file||!$dir||strpos($file,$dir.DIRECTORY_SEPARATOR)!==0){http_response_code(404);exit('File unavailable');}
$mime=['jpg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp','pdf'=>'application/pdf'];$ext=pathinfo($file,PATHINFO_EXTENSION);header('Content-Type: '.($mime[$ext]??'application/octet-stream'));header('X-Content-Type-Options: nosniff');header('Content-Disposition: attachment; filename="'.str_replace(['"',"\r","\n"],'_',basename($row['attachment_original']?:'attachment.'.$ext)).'"');header('Content-Length: '.filesize($file));readfile($file);
